/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { checkout } from './src/app.js';
import { makeReceiptKey } from './src/billing/receipt.js';

const answer = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer), ['owner_file', 'owner_symbol', 'outbound_file', 'outbound_symbol', 'call_chain', 'example_key']);
assert.deepEqual(answer.call_chain, ['src/app.js:checkout', 'src/billing/submit.js:submitInvoice', 'src/billing/receipt.js:makeReceiptKey', 'src/transport/invoices.js:sendInvoice']);
const invoice = { accountId: 'acme', sequence: 7 };
let sent;
const result = await checkout(invoice, { post: async (...args) => { sent = args; return 'sent'; } });
assert.equal(result, 'sent');
assert.equal(makeReceiptKey(invoice), answer.example_key);
assert.deepEqual(sent, ['/invoices', invoice, { 'Idempotency-Key': answer.example_key }]);
console.log('JSON structure and checkout outbound header verified');
NODE"

